import 'package:flutter/material.dart';import '../models/app_models.dart';
class ResultCard extends StatelessWidget{const ResultCard({super.key,required this.result});final EngineResult result;@override Widget build(BuildContext c)=>Card(child:Padding(padding:const EdgeInsets.all(22),child:Wrap(spacing:36,runSpacing:18,children:[metric('Original',format(result.originalSize)),metric('Output',format(result.outputSize)),metric('Saving','${result.saving.toStringAsFixed(2)}%'),metric('Ratio','${result.ratio.toStringAsFixed(3)}x'),metric('Bits/byte',result.bitsPerByte.toStringAsFixed(3)),metric('Integrity',result.sha256==null?'Container verified':'SHA-256 verified')])));Widget metric(String a,String b)=>SizedBox(width:135,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(a),const SizedBox(height:6),Text(b,style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold))]));String format(int x)=>x>1048576?'${(x/1048576).toStringAsFixed(2)} MiB':'${(x/1024).toStringAsFixed(2)} KiB';}
